insert into public.flashcards(id,polish,translation,example,position,is_active,source_metadata) values
('a2work-doswiadczenie','doświadczenie','опыт','Mam dwa lata doświadczenia w sprzedaży.',226,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-obowiazek','obowiązek','обязанность','Moim obowiązkiem jest kontakt z klientami.',227,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-zadanie','zadanie','задача','Dziś mam trzy ważne zadania.',228,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-spotkanie','spotkanie','встреча','Spotkanie zespołu zaczyna się o dziewiątej.',229,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-termin','termin','срок','Termin projektu jest w piątek.',230,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-zespol','zespół','команда','Pracuję w pięcioosobowym zespole.',231,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-kierownik','kierownik','руководитель','Kierownik wyjaśnił mi nowe zadanie.',232,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-zmiana','zmiana','смена','Moja zmiana kończy się o siedemnastej.',233,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),
('a2work-przygotowywac','przygotowywać','подготавливать (процесс)','Codziennie przygotowuję raporty.',234,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-przygotowac','przygotować','подготовить (результат)','Przygotuję raport do południa.',235,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-pisac','pisać','писать','Teraz piszę wiadomość do klienta.',236,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-napisac','napisać','написать','Napiszę wiadomość przed spotkaniem.',237,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-rozwiazywac','rozwiązywać','решать (процесс)','Często rozwiązuję problemy klientów.',238,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-rozwiazac','rozwiązać','решить','Musimy rozwiązać ten problem dzisiaj.',239,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}'),('a2work-awans','awans','повышение','Po roku dostała awans.',240,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
insert into public.lesson_flashcards(lesson_id,flashcard_id,position) values ('a2work-words','a2work-doswiadczenie',0),('a2work-words','a2work-obowiazek',1),('a2work-words','a2work-zadanie',2),('a2work-words','a2work-spotkanie',3),('a2work-words','a2work-termin',4),('a2work-words','a2work-zespol',5),('a2work-words','a2work-kierownik',6),('a2work-words','a2work-zmiana',7),('a2work-review','a2work-przygotowywac',0),('a2work-review','a2work-przygotowac',1),('a2work-review','a2work-pisac',2),('a2work-review','a2work-napisac',3),('a2work-review','a2work-rozwiazywac',4),('a2work-review','a2work-rozwiazac',5),('a2work-review','a2work-awans',6);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('a2work-grammar','Codziennie ___ raporty.','["przygotowuję","przygotuję raz","przygotował jutro"]',0,'Повторяющийся процесс выражает несовершенный вид: przygotowuję.',0),('a2work-grammar','Muszę ___ raport do dwunastej.','["przygotowywać bez końca","przygotować","przygotowałem"]',1,'Важен завершённый результат к сроку: przygotować.',1),('a2work-grammar','Wczoraj przez godzinę ___ wiadomość.','["pisałam","napiszę","napisać"]',0,'Длительность процесса в прошлом передаёт несовершенный pisać: pisałam.',2),('a2work-grammar','Она решила проблему за десять минут.','["Rozwiązywała problem codziennie.","Rozwiązała problem w dziesięć minut.","Rozwiąże problem wczoraj."]',1,'Завершённый единичный результат: rozwiązała.',3),('a2work-grammar','Najpierw ___ dane, a potem wyślę raport.','["sprawdzę","sprawdzałem codziennie","sprawdzać wczoraj"]',0,'Последовательность завершённых будущих действий требует совершенного sprawdzę.',4),
('a2work-quiz','Что означает obowiązek?','["обязанность","отпуск","зарплата"]',0,'Obowiązek — обязанность или служебная задача.',0),('a2work-quiz','Co tydzień ___ wyniki.','["analizuję","przeanalizuję raz","przeanalizowałem jutro"]',0,'Регулярное действие: несовершенный analizuję.',1),('a2work-quiz','Do końca dnia ___ prezentację.','["robię zawsze","zrobię","robiłem jutro"]',1,'Результат к концу дня: совершенный zrobię.',2),('a2work-quiz','Как сказать «у меня опыт в продажах»?','["Mam doświadczenie w sprzedaży.","Jestem termin sprzedażą.","Robię awans klientem."]',0,'Mam doświadczenie w sprzedaży — естественная конструкция об опыте.',3),('a2work-quiz','Kierownik ___ mi zadanie wczoraj.','["wyjaśnił","wyjaśnia jutro","wyjaśnić"]',0,'Однократное завершённое действие в прошлом: wyjaśnił.',4),('a2work-quiz','Teraz ___ problem klienta.','["rozwiązuję","rozwiążę wczoraj","rozwiązałem jutro"]',0,'Teraz указывает на текущий процесс: rozwiązuję.',5),('a2work-quiz','Что обозначает termin проекта?','["команду","крайний срок","рабочее место"]',1,'Termin — назначенная дата или крайний срок.',6),('a2work-quiz','Najpierw napiszemy ofertę, potem ją ___.','["wyślemy","wysyłaliśmy co dzień","wysłać wczoraj"]',0,'Следующий завершённый этап в будущем: wyślemy.',7),
('a2work-reading-check','Gdzie zaczęła pracować Maja?','["W małej firmie informatycznej","W szkole językowej","W restauracji"]',0,'Майя начала работу в небольшой IT-компании.',0),('a2work-reading-check','Co Maja robi codziennie rano?','["Prowadzi szkolenie","Sprawdza pocztę i planuje zadania","Kończy zmianę"]',1,'Каждое утро она проверяет почту и планирует задачи.',1),('a2work-reading-check','Jakie zadanie dostała od kierownika?','["Przygotować raport dla klienta","Zatrudnić nowy zespół","Zmienić biuro"]',0,'Руководитель поручил подготовить отчёт для клиента.',2),('a2work-reading-check','Kto pomógł Mai z tabelą?','["Klient","Kolega z zespołu","Kierownik banku"]',1,'Коллега показал ей, как быстрее заполнить таблицу.',3),('a2work-reading-check','Dlaczego Maja była zadowolona w piątek?','["Skończyła raport przed terminem","Dostała urlop na miesiąc","Nie miała żadnych zadań"]',0,'Она закончила отчёт раньше срока и получила похвалу.',4);
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('pierwszy-tydzien-mai','a2-work','Pierwszy tydzień Mai','Новые обязанности и первый результат на работе','A2',5,'💼','["Maja zaczęła pracować w małej firmie informatycznej. Ma już doświadczenie w obsłudze klientów, ale wcześniej nie pracowała w takim zespole. Codziennie rano sprawdza pocztę, planuje zadania i uczestniczy w krótkim spotkaniu z kierownikiem.","We wtorek kierownik poprosił Maję, żeby przygotowała raport dla ważnego klienta. Najpierw analizowała dane, a potem zaczęła pisać podsumowanie. Nie wiedziała, jak szybko uzupełnić jedną tabelę, więc poprosiła kolegę o pomoc. Kolega pokazał jej prostszy sposób.","W czwartek Maja skończyła raport i wysłała go kierownikowi. Następnego dnia dostała odpowiedź: raport był jasny i dokładny. Maja była zadowolona, bo wykonała zadanie przed terminem. W przyszłym tygodniu będzie rozwiązywać podobne problemy samodzielnie i przygotuje pierwszą prezentację dla klienta."]','{"zaczęła":{"lemma":"zacząć","translation":"начать","part_of_speech":"глагол"},"obsłudze":{"lemma":"obsługa","translation":"обслуживание","part_of_speech":"существительное"},"uczestniczy":{"lemma":"uczestniczyć","translation":"участвовать","part_of_speech":"глагол"},"poprosił":{"lemma":"poprosić","translation":"попросить","part_of_speech":"глагол"},"analizowała":{"lemma":"analizować","translation":"анализировать","part_of_speech":"глагол"},"podsumowanie":{"lemma":"podsumowanie","translation":"итог; резюме","part_of_speech":"существительное"},"uzupełnić":{"lemma":"uzupełnić","translation":"заполнить; дополнить","part_of_speech":"глагол"},"skończyła":{"lemma":"skończyć","translation":"закончить","part_of_speech":"глагол"},"dokładny":{"lemma":"dokładny","translation":"точный","part_of_speech":"прилагательное"},"wykonała":{"lemma":"wykonać","translation":"выполнить","part_of_speech":"глагол"},"samodzielnie":{"lemma":"samodzielnie","translation":"самостоятельно","part_of_speech":"наречие"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-28","comprehension_lesson_id":"a2work-reading-check"}',15,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
